def order_by_points(nums):
    def digits_sum(n):
        neg = 1
        if n < 0:
            n, neg = -n, -1
        ds = [int(i) for i in str(n)]
        ds[0] = ds[0] * neg
        return sum(ds)
    return sorted(nums, key=digits_sum)

def is_nested(string):
    n = len(string)
    after = [0] * (n + 1)
    for i in range(n - 1, -1, -1):
        after[i] = after[i + 1] + (1 if string[i] == ']' else 0)
    seen_open = 0
    for j, ch in enumerate(string):
        if ch == '[':
            if seen_open >= 1 and after[j] >= 2:
                return True
            seen_open += 1
    return False

def tri(n):
    if n == 0:
        return [1]
    my_tri = [1, 3]
    for i in range(2, n + 1):
        if i % 2 == 0:
            my_tri.append(i // 2 + 1)
        else:
            my_tri.append(my_tri[i - 1] + my_tri[i - 2] + 1 + (i + 1) // 2)
    return my_tri[:n + 1]

def find_zero(xs: list):
    begin, end = -1.0, 1.0
    while poly(xs, begin) * poly(xs, end) > 0:
        begin *= 2.0
        end *= 2.0
    while end - begin > 1e-10:
        center = (begin + end) / 2.0
        if poly(xs, center) * poly(xs, begin) > 0:
            begin = center
        else:
            end = center
    return begin


import math


def poly(xs: list, x: float):
    return sum([coeff * math.pow(x, i) for i, coeff in enumerate(xs)])

def intersection(interval1, interval2):
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num ** 0.5) + 1):
            if num % i == 0:
                return False
        return True
    l = max(interval1[0], interval2[0])
    r = min(interval1[1], interval2[1])
    length = r - l
    if length > 0 and is_prime(length):
        return "YES"
    return "NO"

def check_if_last_char_is_a_letter(txt):
    if not txt:
        return False
    last_word = txt.split(' ')[-1]
    if len(last_word) != 1:
        return False
    return 'a' <= last_word.lower() <= 'z'

def count_nums(arr):
    def digits_sum(n):
        neg = 1
        if n < 0:
            n, neg = -n, -1
        ds = [int(i) for i in str(n)]
        ds[0] = ds[0] * neg
        return sum(ds)
    return len([i for i in arr if digits_sum(i) > 0])

def encode(message):
    vowels = "aeiou"
    out = []
    for c in message.swapcase():
        if c.lower() in vowels:
            s = chr(ord(c.lower()) + 2)
            out.append(s.upper() if c.isupper() else s)
        else:
            out.append(c)
    return "".join(out)

def starts_one_ends(n):
    if n == 1:
        return 1
    return 18 * (10 ** (n - 2))

def circular_shift(x, shift):
    s = str(x)
    if shift > len(s):
        return s[::-1]
    if shift == 0:
        return s
    return s[-shift:] + s[:-shift]

def minPath(grid, k):
    n = len(grid)
    val = n * n + 1
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                temp = []
                if i != 0:
                    temp.append(grid[i - 1][j])
                if j != 0:
                    temp.append(grid[i][j - 1])
                if i != n - 1:
                    temp.append(grid[i + 1][j])
                if j != n - 1:
                    temp.append(grid[i][j + 1])
                val = min(temp)
    ans = []
    for i in range(k):
        if i % 2 == 0:
            ans.append(1)
        else:
            ans.append(val)
    return ans

def is_bored(S):
    import re
    sentences = re.split(r'[.?!]\s*', S)
    return sum(1 for sentence in sentences if sentence[:2] == 'I ')

def max_fill(grid, capacity):
    import math
    return sum([math.ceil(sum(arr) / capacity) for arr in grid])

def maximum(arr, k):
    if k == 0:
        return []
    arr.sort()
    return arr[-k:]

def split_words(txt):
    if " " in txt:
        return txt.split()
    elif "," in txt:
        return txt.replace(',', ' ').split()
    else:
        return len([i for i in txt if i.islower() and (ord(i) - 97) % 2 == 1])

def is_sorted(lst):
    count_digit = dict([(i, 0) for i in lst])
    for i in lst:
        count_digit[i] += 1
    if any(count_digit[i] > 2 for i in lst):
        return False
    if all(lst[i - 1] <= lst[i] for i in range(1, len(lst))):
        return True
    else:
        return False

def fix_spaces(text):
    new_text = ""
    i = 0
    start, end = 0, 0
    while i < len(text):
        if text[i] == " ":
            end += 1
        else:
            if end - start > 2:
                new_text += "-" + text[i]
            elif end - start > 0:
                new_text += "_" * (end - start) + text[i]
            else:
                new_text += text[i]
            start, end = i + 1, i + 1
        i += 1
    if end - start > 2:
        new_text += "-"
    elif end - start > 0:
        new_text += "_"
    return new_text

def do_algebra(operator, operand):
    expression = str(operand[0])
    for oprt, oprn in zip(operator, operand[1:]):
        expression += oprt + str(oprn)
    return eval(expression)

def get_closest_vowel(word):
    if len(word) < 3:
        return ""
    vowels = {"a", "e", "i", "o", "u", "A", "E", "I", "O", "U"}
    for i in range(len(word) - 2, 0, -1):
        if word[i] in vowels and word[i + 1] not in vowels and word[i - 1] not in vowels:
            return word[i]
    return ""
